"""Native cache-only fixtures: generated bytes/fake frames, no network or sensor."""
import argparse
import ctypes
import json
import os
from pathlib import Path
import sys
import time
import uuid
from unittest.mock import patch

import image_verification as verify
import verify_image_stage as original
import verify_frame_access

stage = verify.stage
ROOT = verify.admission.REPO / '.runtime/cache-verification-rehearsals'
CASES = ('success', 'publication-window', 'cpu-hot', 'reader-exit', 'read-sharing', 'blocked-cache', 'cancel')


def checked(directory):
    directory = Path(directory).absolute()
    stage.download.tools.plain(directory)
    if (directory.parents[1] != ROOT or directory.name not in CASES or
            not stage.stage_session_id(directory.parent.name)):
        raise ValueError('Fixed cache-verification fixture namespace required')
    return directory


def packet():
    result, config, packed = original.fixture()
    result.update(operation='verify-retained-cache-only', inputBytes=len(config)+len(packed),
                  writeNamespaceBytes=4*1024**2)
    return result, config, packed


class Feed(original.Feed):
    def poll(self):
        if (self.directory/'blocked').exists():
            if self.directory.name == 'reader-exit':
                self.observed_exit_code = 7
                self.operation = 'liveness'
                raise stage.cpu_feed.FeedError('READER_EXITED')
            if self.directory.name == 'read-sharing':
                self.operation = 'read'
                error = PermissionError(13, 'synthetic secret must not be logged')
                error.winerror = 32
                raise error
        frame=super().poll()
        if frame is not None and self.directory.name=='publication-window':
            with verify_frame_access.published_frame(self.directory,frame['sequence'],json.dumps(frame).encode()) as path:
                frame=json.loads(stage.cpu_feed.sensor_frame_io.read(path))
        return frame


def child(directory):
    directory = checked(directory)
    spec, _, _ = packet()
    kernel = stage.windows_job.api()
    allowed, system = ctypes.c_size_t(), ctypes.c_size_t()
    stage.windows_job.checked(kernel.GetProcessAffinityMask(kernel.GetCurrentProcess(), ctypes.byref(allowed), ctypes.byref(system)))
    stage.download.tools.base.atomic(directory/'affinity.json', {'logicalProcessors':allowed.value.bit_count()})
    base_layer = stage.expand._layer
    def layer(*args, **kwargs):
        if directory.name not in ('success','publication-window'):
            (directory/'blocked').touch(exist_ok=True)
            time.sleep(30)
        return base_layer(*args, **kwargs)
    with patch.object(stage.expand, '_layer', side_effect=layer), \
            patch.object(stage.download, 'RegistrySource', side_effect=AssertionError('No network in verification')):
        verify.pipeline(directory, spec, directory/'cache', synthetic=True)


def supervise(directory):
    directory = checked(directory)
    spec, _, _ = packet()
    feed = Feed(directory)
    def launch():
        env = {k:os.environ[k] for k in ('SystemRoot','TEMP','TMP') if k in os.environ}
        return stage.windows_job.Process([sys.executable,'-B','-E','-s',str(Path(__file__).resolve()),
                   '--synthetic-child',str(directory)],cwd=directory,env=env,single_cpu=True)
    return stage._execute(directory,spec,feed,launch,synthetic=True,validate=verify.validate_result),feed


def rehearse():
    directory = ROOT/uuid.uuid4().hex
    directory.mkdir(parents=True)
    result = {'version':1,'status':'RUNNING','synthetic':True,'cases':{},
              'networkRequests':0,'realSensorReads':0,'realBlobReads':0,
              'imageImportEnabled':False,'buildEnabled':False,'modelLaunchEnabled':False}
    for name in CASES:
        target = directory/name
        target.mkdir()
        cache = target/'cache'
        cache.mkdir()
        spec,config,packed = packet()
        (cache/spec['image']['configDigest'][7:]).write_bytes(config)
        (cache/spec['image']['layers'][0]['digest'][7:]).write_bytes(packed)
        before = {p.name:stage.download.tools.sha(p) for p in cache.iterdir()}
        state, feed = supervise(target)
        assert state['stopConfirmed'] and state['readerStopped'] and feed.closed
        assert state['phase'] == ('COMPLETE' if name in ('success','publication-window') else 'FAULT'), (name,state)
        assert not state['imageDownloadEnabled']
        assert json.loads((target/'affinity.json').read_bytes())['logicalProcessors']==1
        assert before == {p.name:stage.download.tools.sha(p) for p in cache.iterdir()}
        if name=='reader-exit':
            assert state['sensorFeedError']['reason']=='READER_EXITED'
            assert state['sensorFeedError']['readerExitCode']==7
        if name=='read-sharing':
            assert state['sensorFeedError']['windowsError']==32
            assert 'secret' not in json.dumps(state)
        try:
            supervise(target)
            raise AssertionError('Consumed fixture restarted')
        except stage.download.StageError as error:
            assert error.code=='IMAGE_STAGE_RESTART_REJECTED'
        result['cases'][name]={'phase':state['phase'],'fault':state['fault'],
            'workerStopped':state['stopConfirmed'],'readerStopped':state['readerStopped'],
            'stopSeconds':state.get('workerStopElapsedSeconds'),'cacheUnchanged':True,
            'restartRejected':True,'sensorFeedError':state.get('sensorFeedError')}
    result['status']='PASSED'
    stage.download.tools.base.atomic(directory/'result.json',result)
    return {'directory':str(directory),**result}


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--synthetic-child',type=Path)
    options=parser.parse_args()
    if options.synthetic_child:
        try:
            child(options.synthetic_child)
        except BaseException:
            raise SystemExit(3)
    else:
        print(json.dumps(rehearse(),indent=2))
